let currentProtocol = 'tcp';
let isTransmitting = false;

function selectProtocol(proto) {
  currentProtocol = proto;
  const btnTcp = document.getElementById('btn-proto-tcp');
  const btnUdp = document.getElementById('btn-proto-udp');
  if (proto === 'tcp') {
    btnTcp.className = 'px-3 py-1 text-xs font-mono font-bold rounded-lg bg-amber-500 text-stone-900 border border-amber-400';
    btnUdp.className = 'px-3 py-1 text-xs font-mono font-bold rounded-lg bg-stone-800 text-stone-300 border border-stone-700 hover:bg-stone-700';
  } else {
    btnUdp.className = 'px-3 py-1 text-xs font-mono font-bold rounded-lg bg-blue-500 text-white border border-blue-400';
    btnTcp.className = 'px-3 py-1 text-xs font-mono font-bold rounded-lg bg-stone-800 text-stone-300 border border-stone-700 hover:bg-stone-700';
  }
  resetSimulationVisuals();
}

function resetSimulationVisuals() {
  document.getElementById('sender-queue').innerHTML = '<span class="px-2 py-0.5 rounded bg-stone-800 text-stone-300">Ready</span>';
  document.getElementById('network-pipe').innerHTML = '<span class="text-stone-500 text-[10px] italic">Idle</span>';
  document.getElementById('kernel-buffer').innerHTML = '<span class="text-stone-500 text-[10px] italic">Buffer empty</span>';
  document.getElementById('app-read-stream').innerHTML = '<span class="text-stone-500 italic text-xs">Waiting for application to consume stream...</span>';
  document.getElementById('hol-badge').textContent = 'STATUS: IDLE';
  document.getElementById('hol-badge').className = 'text-[10px] px-2 py-0.5 rounded bg-stone-800 text-stone-400';
  document.getElementById('tel-hol').textContent = '0 ms';
  document.getElementById('tel-hol').className = 'text-sm font-bold text-stone-300 mt-0.5';
  document.getElementById('tel-buf').textContent = '0 Packets';
  document.getElementById('tel-app').textContent = '0 / 5';
  document.getElementById('tel-cwnd').textContent = 'Normal (100%)';
  document.getElementById('tel-cwnd').className = 'text-sm font-bold text-emerald-400 mt-0.5';
  document.getElementById('btn-retransmit').classList.add('hidden');
}

function runSimulation() {
  if (isTransmitting) return;
  isTransmitting = true;
  resetSimulationVisuals();

  const dropPkt2 = document.getElementById('chk-drop-pkt2').checked;
  const log = document.getElementById('sim-log');
  const senderQ = document.getElementById('sender-queue');
  const pipe = document.getElementById('network-pipe');
  const kernelBuf = document.getElementById('kernel-buffer');
  const appStream = document.getElementById('app-read-stream');

  log.innerHTML = `<strong>[START]</strong> Transmitting 5 packets (MSS 1460B each) via <strong>${currentProtocol.toUpperCase()}</strong>...`;

  senderQ.innerHTML = `
    <span class="px-1.5 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-800">#1</span>
    <span class="px-1.5 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-800">#2</span>
    <span class="px-1.5 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-800">#3</span>
    <span class="px-1.5 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-800">#4</span>
    <span class="px-1.5 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-800">#5</span>
  `;

  setTimeout(() => {
    pipe.innerHTML = '';
    for (let i = 1; i <= 5; i++) {
      if (i === 2 && dropPkt2) {
        pipe.innerHTML += `<span class="px-1.5 py-0.5 rounded bg-rose-950 text-rose-300 border border-rose-800 line-through">#2 (DROP)</span> `;
      } else {
        pipe.innerHTML += `<span class="px-1.5 py-0.5 rounded bg-stone-800 text-stone-200">#${i}</span> `;
      }
    }
    log.innerHTML += `<br/><strong>[WIRE]</strong> Packets in transit across 60ms RTT link (30ms one-way). Router buffer drops Packet #2.`;

    setTimeout(() => {
      kernelBuf.innerHTML = '';
      appStream.innerHTML = '';

      if (currentProtocol === 'tcp') {
        if (dropPkt2) {
          // Packet 1 delivered
          appStream.innerHTML = `<span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">ByteSeq #1 [1-1460]</span>`;
          // Packets 3, 4, 5 held in kernel
          kernelBuf.innerHTML = `
            <span class="px-2 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-700">Held: #3</span>
            <span class="px-2 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-700">Held: #4</span>
            <span class="px-2 py-0.5 rounded bg-amber-950 text-amber-300 border border-amber-700">Held: #5</span>
          `;
          document.getElementById('hol-badge').textContent = '⚠️ HEAD-OF-LINE STALL DETECTED';
          document.getElementById('hol-badge').className = 'text-[10px] font-mono font-bold px-2 py-0.5 rounded bg-rose-950 text-rose-300 border border-rose-800';
          document.getElementById('tel-hol').textContent = '60 ms stall (+1 RTT)';
          document.getElementById('tel-hol').className = 'text-sm font-bold text-rose-400 mt-0.5';
          document.getElementById('tel-buf').textContent = '3 Packets (4,380 B)';
          document.getElementById('tel-app').textContent = '1 / 5 (Frozen)';
          document.getElementById('tel-cwnd').textContent = 'Throttled (-50%)';
          document.getElementById('tel-cwnd').className = 'text-sm font-bold text-rose-400 mt-0.5';

          log.innerHTML += `<br/><span class="text-rose-400 font-bold">[TCP STALL]</span> Packet #2 missing! Receiver sent 3 Duplicate ACKs (ACK 1461). Kernel holds Packets #3, #4, #5 in receive buffer until #2 arrives. Application read() is blocked for an extra 60 ms (1 RTT)!`;
          document.getElementById('btn-retransmit').classList.remove('hidden');
        } else {
          appStream.innerHTML = `
            <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">#1</span>
            <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">#2</span>
            <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">#3</span>
            <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">#4</span>
            <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">#5</span>
          `;
          kernelBuf.innerHTML = '<span class="text-stone-500 text-[10px] italic">Flushed</span>';
          document.getElementById('hol-badge').textContent = '✅ STREAM COMPLETE (5/5)';
          document.getElementById('hol-badge').className = 'text-[10px] font-mono font-bold px-2 py-0.5 rounded bg-emerald-950 text-emerald-300 border border-emerald-800';
          document.getElementById('tel-app').textContent = '5 / 5 (Clean)';
          log.innerHTML += `<br/><span class="text-emerald-400">[TCP SUCCESS]</span> All 5 packets arrived in order. Stream cleanly consumed by application.`;
        }
      } else {
        // UDP mode
        if (dropPkt2) {
          appStream.innerHTML = `
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #1</span>
            <span class="px-2 py-1 rounded bg-stone-900 text-stone-500 border border-stone-800 italic line-through">Datagram #2 (Lost)</span>
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #3</span>
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #4</span>
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #5</span>
          `;
          kernelBuf.innerHTML = '<span class="text-emerald-400 text-[10px]">Zero hold buffer. Immediate pass-through.</span>';
          document.getElementById('hol-badge').textContent = '⚡ ZERO STALL (UDP PASSTHROUGH)';
          document.getElementById('hol-badge').className = 'text-[10px] font-mono font-bold px-2 py-0.5 rounded bg-blue-950 text-blue-300 border border-blue-800';
          document.getElementById('tel-hol').textContent = '0 ms (No Stall)';
          document.getElementById('tel-hol').className = 'text-sm font-bold text-emerald-400 mt-0.5';
          document.getElementById('tel-buf').textContent = '0 B (Stateless)';
          document.getElementById('tel-app').textContent = '4 / 5 Delivered';
          document.getElementById('tel-cwnd').textContent = 'N/A (No Throttling)';
          document.getElementById('tel-cwnd').className = 'text-sm font-bold text-stone-400 mt-0.5';

          log.innerHTML += `<br/><span class="text-blue-400 font-bold">[UDP DELIVER]</span> Datagram #2 dropped by router. Kernel immediately delivered #3, #4, and #5 to application socket with 0 ms Head-of-Line delay. Jitter buffer/PLC handles the missing frame.`;
        } else {
          appStream.innerHTML = `
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #1</span>
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #2</span>
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #3</span>
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #4</span>
            <span class="px-2 py-1 rounded bg-blue-950 text-blue-300 border border-blue-800">Datagram #5</span>
          `;
          kernelBuf.innerHTML = '<span class="text-stone-500 text-[10px] italic">Zero hold buffer</span>';
          document.getElementById('hol-badge').textContent = '⚡ COMPLETE (5/5)';
          document.getElementById('hol-badge').className = 'text-[10px] font-mono font-bold px-2 py-0.5 rounded bg-blue-950 text-blue-300 border border-blue-800';
          document.getElementById('tel-app').textContent = '5 / 5';
        }
      }
      isTransmitting = false;
    }, 600);
  }, 400);
}

function triggerFastRetransmit() {
  const pipe = document.getElementById('network-pipe');
  const log = document.getElementById('sim-log');
  const kernelBuf = document.getElementById('kernel-buffer');
  const appStream = document.getElementById('app-read-stream');

  log.innerHTML += `<br/><span class="text-amber-400 font-bold">[FAST RETRANSMIT]</span> Sender received 3 Dup ACKs. Retransmitting Packet #2 across wire...`;
  pipe.innerHTML = `<span class="px-2 py-0.5 rounded bg-amber-500 text-stone-900 font-bold animate-bounce">⚡ #2 RETRANSMIT</span>`;

  setTimeout(() => {
    pipe.innerHTML = '<span class="text-emerald-400 text-[10px]">Delivered</span>';
    kernelBuf.innerHTML = '<span class="text-emerald-400 text-[10px]">Flushed. All bytes contiguous.</span>';
    appStream.innerHTML = `
      <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">ByteSeq #1</span>
      <span class="px-2 py-1 rounded bg-amber-500 text-stone-900 font-bold border border-amber-400">ByteSeq #2 (Recovered)</span>
      <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">ByteSeq #3</span>
      <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">ByteSeq #4</span>
      <span class="px-2 py-1 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">ByteSeq #5</span>
    `;
    document.getElementById('hol-badge').textContent = '✅ RESOLVED AFTER 60 MS STALL';
    document.getElementById('hol-badge').className = 'text-[10px] font-mono font-bold px-2 py-0.5 rounded bg-emerald-950 text-emerald-300 border border-emerald-800';
    document.getElementById('tel-hol').textContent = '60 ms Extra Stall (90 ms total)';
    document.getElementById('tel-hol').className = 'text-sm font-bold text-amber-400 mt-0.5';
    document.getElementById('tel-buf').textContent = '0 B (Flushed)';
    document.getElementById('tel-app').textContent = '5 / 5 (Complete)';
    document.getElementById('btn-retransmit').classList.add('hidden');
    log.innerHTML += `<br/><span class="text-emerald-400 font-bold">[FLUSHED]</span> Packet #2 arrived at t = 90 ms. Kernel reassembled stream and released bytes 1461-7300 to application. Total delivery: 90 ms (extra wait: 60 ms).`;
  }, 600);
}
